function terminalStopProof(f,accounting=f.b.snapshot()){
 const recordedAt=new Date(f.now()).toISOString(),resultPath=join(f.directory,'terminal-result.json'),tracePath=join(f.directory,'terminal-trace.jsonl'),outcome={ok:false,error:{kind:'WorkflowStageProviderRetryLimitReached'}};writeFileSync(resultPath,JSON.stringify({version:'openlearn-six-page-pipeline-result-v1',recordedAt,outcome,cleanup:{ok:true},accounting}));writeFileSync(tracePath,JSON.stringify({at:recordedAt,phase:'pipeline-stopped',outcome,cleanup:{ok:true},accounting})+'\n');return {resultPath,resultSha256:hash(readFileSync(resultPath)),tracePath,traceSha256:hash(readFileSync(tracePath))};
}
