test('already-paused cleanup rejects stale accounting, changed proof bytes, failed cleanup or a new physical dispatch',async()=>{
 for(const failure of ['stale','hash','cleanup','dispatch']){const f=await standingFixture();try{f.b.authorizeFailedReviewCostPolicy(f.policyCommand);const before=f.b.snapshot();f.advance(1000);const state=f.b.snapshot();if(failure==='stale')state.current.requests++;const proof=terminalStopProof(f,state);if(failure==='hash')writeFileSync(proof.resultPath,'changed immutable proof');if(failure==='cleanup'){const result=JSON.parse(readFileSync(proof.resultPath));result.cleanup.ok=false;writeFileSync(proof.resultPath,JSON.stringify(result));proof.resultSha256=hash(readFileSync(proof.resultPath));}if(failure==='dispatch'){const db=new DatabaseSync(f.storePath);try{db.prepare('INSERT INTO pipeline_dispatches VALUES(?,?)').run('synthetic-impossible-new-dispatch',f.now());db.prepare('INSERT INTO pipeline_outcomes VALUES(?,?)').run('synthetic-impossible-new-dispatch',f.now());}finally{db.close();}}assert.throws(()=>f.b.pauseForPreparation(proof),/PipelinePreparation(?:Proof|Pause)Invalid/);assert.deepEqual(f.b.snapshot().physicalIntervals,before.physicalIntervals);assert.equal(f.b.snapshot().remainingMilliseconds,before.remainingMilliseconds);assert.equal(f.calls(),1);f.assertPrior();}finally{f.close();}}
});
