 for(const change of [a=>a.ownerAuthorized=false,a=>a.identity.ownerId='foreign',a=>a.identity.runId='foreign',a=>a.source='Remove the ceiling',a=>a.continuationSource='Stop after1.50',a=>a.models.push('unauthorized/model'),a=>a.maximumRequests=1201,a=>a.additionalMilliseconds=1800000,a=>a.effectiveDeadlineAtMs++,a=>a.modelCostNotificationThresholdNanodollars=2000000000,a=>a.cumulativeBrowserCreditLimit=151]){const f=await executionOverrideFixture();try{const before=f.b.snapshot();change(f.authority);writeFileSync(f.overridePath,JSON.stringify(f.authority));assert.throws(()=>f.b.authorizeExecutionOverride(f.overrideCommand()),/ExecutionOverrideInvalid/);assert.deepEqual(f.b.snapshot(),before);assertSecondHistoryUnchanged(f);}finally{f.close();}}
